--liquibase formatted sql
-- PostgreSQL conversion of the corresponding XML changelog.
--changeset interview-portal:016-create-candidate-history
CREATE TABLE "candidate_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "candidate_id" BIGINT,
    "first_name" VARCHAR(255),
    "last_name" VARCHAR(255),
    "email" VARCHAR(255),
    "experience" INTEGER,
    "designation" VARCHAR(255),
    "is_active" BOOLEAN,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT,
    "comment" VARCHAR(100),
    "last_appeared_at" TIMESTAMP,
    "deleted_by" BIGINT,
    "deleted_at" TIMESTAMP,
    "result" VARCHAR(255),
    "ai_score" INTEGER,
    "action_performed" VARCHAR(20)
);
